{
  "units": [
    {
      "quote": "Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Provides introductory background context clarifying that photographing infants presents unique challenges and sets the general standard of seeking the best likeness reasonably obtainable."
    },
    {
      "quote": "It is acceptable if the infant's eyes, particularly a newborn's, are partially or completely closed;",
      "scope_quotes": [
        "Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "permission",
      "meaning": "For infant photographs, it is permissible for the infant's eyes (specifically including newborns) to be either partially or entirely closed."
    },
    {
      "quote": "The infant's head may be discreetly supported, e.g., a car seat with a white or off-white blanket behind the child.",
      "scope_quotes": [
        "Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "permission",
      "meaning": "An infant's head is permitted to be discreetly supported, such as by placing the child in a car seat covered with a white or off-white blanket."
    },
    {
      "quote": "Head tilt is acceptable for infants;",
      "scope_quotes": [
        "Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "permission",
      "meaning": "Head tilt is permitted in photographs of infants."
    },
    {
      "quote": "A parent’s face cannot be in the photograph of the infant.",
      "scope_quotes": [
        "Infants pose a particular challenge. The goal is the best likeness that can reasonably be obtained:"
      ],
      "kind": "prohibition",
      "meaning": "A parent's face is strictly prohibited from appearing in an infant's passport photograph."
    },
    {
      "quote": "You must request a new photograph if the photograph submitted does not meet the following requirements:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "An adjudicator or official is required to request a new photograph whenever a submitted photograph fails to comply with the specified photograph requirements."
    },
    {
      "quote": "The photograph must be in color;",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "requirement",
      "meaning": "Submitted photographs are required to be in color."
    },
    {
      "quote": "The photograph should be taken within six months of submitting the application, be a good likeness of and satisfactorily identify the applicant at the time of the application (see 22 CFR 51.26).",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "recommendation",
      "meaning": "Photographs should be taken within six months prior to submitting the passport application, and they should present a good likeness that satisfactorily identifies the applicant at application time pursuant to 22 CFR 51.26."
    },
    {
      "quote": "A photograph showing a change in hairstyle or facial hair from the identification document submitted is acceptable if it still is a good likeness of the applicant;",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "permission",
      "meaning": "A photograph displaying a different hairstyle or facial hair compared to the submitted identification document is acceptable provided it continues to represent a good likeness of the applicant."
    },
    {
      "quote": "Applicants may wish to re-use a passport photograph that is depicted on their submitted U.S Certificate of Citizenship or Certificate of Naturalization. Be aware that even if the certificate itself was recently issued, because of U.S. Citizenship and Immigration Services processing times, the photograph may not have been taken within six months of submitting the application.",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "statement",
      "meaning": "Notifies adjudicators that while applicants may attempt to reuse a photograph appearing on a submitted U.S. Certificate of Citizenship or Naturalization, the photograph might not have been taken within six months of application submission even if the certificate was issued recently, due to USCIS processing timelines."
    },
    {
      "quote": "The photograph must be free of material damage:",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:"
      ],
      "kind": "requirement",
      "meaning": "The submitted photograph is mandatory required to be free from any material damage."
    },
    {
      "quote": "Material damage is any damage to the facial area that makes the photograph no longer a good likeness of the applicant (e.g., creases, large holes, and large smudges) or impedes the functioning of facial recognition (damage in the area of the eyes);",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "The photograph must be free of material damage:"
      ],
      "kind": "definition",
      "meaning": "Defines material damage as any facial area damage that stops the photo from being a good likeness (such as creases, large holes, or large smudges) or any eye-area damage that hinders facial recognition functioning."
    },
    {
      "quote": "Immaterial damage is any damage to the background, and non-material damage to the facial area (e.g., staple holes).",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "The photograph must be free of material damage:"
      ],
      "kind": "definition",
      "meaning": "Defines immaterial damage as damage confined to the background or non-material facial damage such as staple holes."
    },
    {
      "quote": "Immaterial damage is acceptable;",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "The photograph must be free of material damage:"
      ],
      "kind": "permission",
      "meaning": "Photographs that have immaterial damage are permitted and acceptable."
    },
    {
      "quote": "The applicant does not need to sign the photograph, as this often causes creases or smudges; and",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "The photograph must be free of material damage:"
      ],
      "kind": "permission",
      "meaning": "Applicants are not required to sign their photograph, as signing frequently leads to smudges or creases."
    },
    {
      "quote": "For hand-carry applications, the acceptance agent signs the back of the photograph.",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "The photograph must be free of material damage:"
      ],
      "kind": "requirement",
      "meaning": "For hand-carry applications specifically, the acceptance agent must sign the reverse side of the photograph."
    },
    {
      "quote": "A photograph that appears acceptable and undamaged in the system may have a defect that is apparent when the passport is printed. Consequently, the passport application may be returned to adjudication to request a new photograph even though the photograph appeared acceptable.",
      "scope_quotes": [
        "You must request a new photograph if the photograph submitted does not meet the following requirements:",
        "The photograph must be free of material damage:"
      ],
      "kind": "statement",
      "meaning": "Acknowledges that an in-system acceptable photograph might display printing defects when printed on the passport, allowing the passport application to be returned to adjudication for requesting a replacement photograph."
    },
    {
      "quote": "Eyeglasses are not acceptable unless they cannot be removed for medical reasons, e.g., the applicant has recently had ocular surgery and the eyeglasses are necessary to protect the applicant’s eyes.",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:"
      ],
      "kind": "prohibition",
      "meaning": "Eyeglasses are generally barred from passport photographs unless removal is precluded by medical necessity, such as following recent ocular surgery where eyewear is vital for eye protection."
    },
    {
      "quote": "A medical statement signed by a medical professional/health practitioner must be requested in these rare circumstances.",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "Eyeglasses are not acceptable unless they cannot be removed for medical reasons, e.g., the applicant has recently had ocular surgery and the eyeglasses are necessary to protect the applicant’s eyes."
      ],
      "kind": "requirement",
      "meaning": "Whenever eyeglasses cannot be removed for medical reasons, an adjudicator must request a medical statement signed by a medical professional or health practitioner."
    },
    {
      "quote": "The frames of the eyeglasses must not cover the eye(s);",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "prohibition",
      "meaning": "When eyeglasses are approved due to medical reasons, the frames are prohibited from covering any portion of the eye or eyes."
    },
    {
      "quote": "There must not be glare on eyeglasses that obscures the eye(s);",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "prohibition",
      "meaning": "When eyeglasses are accepted for medical reasons, glare on the lenses that obscures the eye or eyes is prohibited."
    },
    {
      "quote": "There must not be shadows or refraction from the eyeglasses that obscure the eye(s); and",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "prohibition",
      "meaning": "When eyeglasses are permitted for medical reasons, shadows or refraction resulting from the eyeglasses that obscure the eye or eyes are prohibited."
    },
    {
      "quote": "Dark or tinted lenses are permitted if the medical statement also indicates that they are required.",
      "scope_quotes": [
        "e. Eyeglasses/contact lenses:",
        "If the eyeglasses are accepted for medical reasons:"
      ],
      "kind": "permission",
      "meaning": "Dark or tinted eyeglass lenses are allowed only on the condition that the signed medical statement expressly confirms they are medically necessary."
    }
  ]
}
